solution.fees/berth.py:
"""Berth dues."""

__all__ = ["fee"]

CLASSES = ['A', 'B', 'C', 'D']
STEP = 4
FIRST = "2019-01-01"
RATES = {'A': [('2019-01-01', 1570)], 'B': [('2019-01-01', 2885)], 'C': [('2019-01-01', 3290), ('2020-10-01', 3091)], 'D': [('2019-01-01', 5180), ('2020-08-01', 4906), ('2022-02-01', 4566)]}
SURCHARGE = [('2019-01-01', 21)]
DISCOUNT = [('2019-01-01', 14)]
MINIMUM = [('2019-01-01', 3350)]
CAP = [('2019-01-01', None)]
ROUND = 5


def _at(history, on):
    value = None
    for since, v in history:
        if since <= on:
            value = v
    return value


def _ratio(n, d):
    return (2 * n + d) // (2 * d)


def fee(cls, qty, on, night=False, regular=False):
    if cls not in CLASSES:
        raise ValueError("unknown class")
    if qty < 1:
        raise ValueError("qty must be at least 1")
    if on < FIRST:
        raise ValueError("no tariff before " + FIRST)
    units = -(-qty // STEP)
    amount = _at(RATES[cls], on) * units
    if night:
        amount += _ratio(amount * _at(SURCHARGE, on), 100)
    if regular:
        amount -= _ratio(amount * _at(DISCOUNT, on), 100)
    amount = max(amount, _at(MINIMUM, on))
    cap = _at(CAP, on)
    if cap is not None:
        amount = min(amount, cap)
    return _ratio(amount, ROUND) * ROUND

